-- Let me check if acctbal can be 0 or negative for some traders
SELECT COUNT(*) as total, SUM(CASE WHEN acctbal <= 0 THEN 1 ELSE 0 END) as non_positive
FROM trader;

-- Let me check if maybe the join path is wrong - perhaps compliancecase doesn't always link to enforcementactions
SELECT COUNT(*) FROM compliancecase;
SELECT COUNT(*) FROM enforcementactions;

-- Check how many compliance cases have enforcement actions
SELECT COUNT(DISTINCT ea.compref2) 
FROM enforcementactions ea;

-- Let me check if there's a specific column that identifies "risk cases"
-- Maybe it's about the detectmth or survsys
SELECT DISTINCT detectmth, survsys FROM compliancecase;
